var app=angular.module('validationApp',['ngRoute','ngAnimate']); app.config(function($routeProvider){$routeProvider.when('/home',{template:'<h2>Home route</h2><p>This route is handled by $routeProvider.</p>'}).when('/about',{template:'<h2>About route</h2><p>AngularJS routing example.</p>'}).otherwise({redirectTo:'/home'});}); app.directive('customName',function(){return {require:'ngModel',link:function(s,e,a,ngModel){ngModel.$validators.customName=function(v){return !!v && v.length>=3;};}};}); app.controller('FormCtrl',function($scope){$scope.show=true;$scope.user={};$scope.submit=function(form){$scope.formMessage=form.$valid?'Form submitted successfully.':'Please fix validation errors.';};});
